export default '/**\n * Stackra file contract:\n * Purpose: the "month" demo of the native Scheduler: the month grid, two events a day and "N more" on a busy day; a\n *          date opens its day.\n * Boundary: a demo with no props, @stackra/ui only; the same file is the preview and the code shown.\n * Runtime: react-native\n * Governing contract: showcase redesign spec (2026-10-27) section 4 (demo contract); ADR 0302 (decisions 3 and 5);\n *          ADR 0060 (light, dark, RTL); STA-1371 (gap build, owner approval 2026-10-31).\n */\nimport { getLocalTimeZone, today } from "@internationalized/date";\nimport { Scheduler, useCatalogueText, type SchedulerEvent } from "@stackra/ui/native";\n\nimport { MESSAGES } from "#src/constants/messages.constant";\nimport { SCHEDULER_DEMO_KEYS } from "#src/demos/free/scheduler/scheduler-demo-keys.constant";\n\n/** The demo\'s keys. */\nconst K = SCHEDULER_DEMO_KEYS.demo_free.scheduler;\n\n/** A moment `days` from today, at `hour` (fractions are minutes), in the device\'s time zone. */\nconst at = (days: number, hour: number) =>\n  new Date(\n    today(getLocalTimeZone()).add({ days }).toDate(getLocalTimeZone()).getTime() + hour * 3_600_000,\n  );\n\n/** Scheduler: the month. */\nexport default function Month() {\n  const t = useCatalogueText(MESSAGES.en);\n  const events: SchedulerEvent[] = [\n    { id: "1", title: t(K.checkup), start: at(0, 9), end: at(0, 10) },\n    { id: "2", title: t(K.xray), start: at(0, 9.5), end: at(0, 10.5), tone: "warning" },\n    { id: "3", title: t(K.staff), start: at(0, 13), end: at(0, 14), tone: "default" },\n    { id: "4", title: t(K.cleaning), start: at(1, 11), end: at(1, 12), tone: "success" },\n    { id: "5", title: t(K.consult), start: at(-1, 15), end: at(-1, 16.5) },\n    {\n      id: "6",\n      title: t(K.holiday),\n      start: at(2, 0),\n      end: at(3, 0),\n      isAllDay: true,\n      tone: "danger",\n    },\n  ];\n  return <Scheduler label={t(K.label)} events={events} defaultView="month" />;\n}\n';
